#!/usr/bin/env python3
"""Print the next order id, reading issued ids from ids.txt.

Ids have the form ORD-XXXX where XXXX is a four-digit base-36 code.
ids.txt holds one id per line, most recent last.
"""

from pathlib import Path

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
WIDTH = 4


def increment(code: str) -> str:
    """Return the next base-36 code after the given one."""
    n = 0
    for char in code:
        n = n * len(ALPHABET) + ALPHABET.index(char)

    n += 1
    if n >= len(ALPHABET) ** WIDTH:
        raise ValueError("order id space exhausted")

    result = ""
    for _ in range(WIDTH):
        result = ALPHABET[n % len(ALPHABET)] + result
        n //= len(ALPHABET)
    return result


def main() -> None:
    lines = [
        line.strip()
        for line in Path("ids.txt").read_text().splitlines()
        if line.strip()
    ]
    last = lines[-1]
    code = last.rsplit("-", 1)[1]
    print(f"ORD-{increment(code)}")


if __name__ == "__main__":
    main()

