#!/usr/bin/env python3
"""Generate the next order id."""

import sys


def base36_encode(n):
    """Encode an integer as a 4-character base36 string."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = []
    for _ in range(4):
        result.append(chars[n % 36])
        n //= 36
    return ''.join(reversed(result))


def base36_decode(s):
    """Decode a base36 string to an integer."""
    return int(s, 36)


def main():
    with open('ids.txt', 'r') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet, start from zero
        next_num = 0
    else:
        last_id = lines[-1]
        suffix = last_id.split('-')[1]
        last_num = base36_decode(suffix)
        next_num = last_num + 1

    next_suffix = base36_encode(next_num)
    sys.stdout.write(f'ORD-{next_suffix}\n')


if __name__ == '__main__':
    main()

