#!/usr/bin/env python3
import sys

def base36_encode(n):
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))

def base36_decode(s):
    return int(s, 36)

def next_id(last_id):
    suffix = last_id.split("-")[1]
    n = base36_decode(suffix)
    n += 1
    return "ORD-" + base36_encode(n).zfill(4)

def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    last = lines[-1]
    print(next_id(last))

if __name__ == "__main__":
    main()

