#!/usr/bin/env python3
"""Print the next order id based on the most recent id in ids.txt."""

def to_base36(value, width):
    """Format an integer as an uppercase base36 string of the given width."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    out = []
    for _ in range(width):
        out.append(digits[value % 36])
        value //= 36
    if value:
        raise ValueError("id overflow")
    return "".join(reversed(out))


def main():
    with open("ids.txt", "r", encoding="utf-8") as fh:
        lines = [line.strip() for line in fh if line.strip()]

    if not lines:
        raise SystemExit("ids.txt is empty")

    last = lines[-1]
    prefix, suffix = last[:4], last[4:]

    next_id = int(suffix, 36) + 1
    print(prefix + to_base36(next_id, len(suffix)))


if __name__ == "__main__":
    main()
