#!/usr/bin/env python3
"""Read ids.txt and print the next order id (ORD-XXXX) to stdout."""

import sys

BASE = 36
DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def to_base36(n: int) -> str:
    """Convert an integer to a base-36 string."""
    if n == 0:
        return "0"
    chars = []
    while n > 0:
        chars.append(DIGITS[n % BASE])
        n //= BASE
    return "".join(reversed(chars))

def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * BASE + DIGITS.index(ch.upper())
    return n

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # No ids yet — start from the beginning
        last_num = -1
    else:
        last_id = lines[-1]
        try:
            prefix, suffix = last_id.split("-")
            last_num = from_base36(suffix)
        except (ValueError, IndexError):
            print(f"error: invalid id format: {last_id}", file=sys.stderr)
            sys.exit(1)

    next_num = last_num + 1
    next_suffix = to_base36(next_num).zfill(4)

    # If overflow beyond ZZZZ, just print the longer form (should not happen in practice)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

