def base36_increment(s: str) -> str:
    """Increment a base36 string by 1, returning a string of the same length."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            return ''.join(chars)
        chars[i] = '0'
    # If we overflowed all positions, prefix with '1' (shouldn't happen for our case)
    return '1' + ''.join(chars)


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('Error: ids.txt not found', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('Error: ids.txt is empty', file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]  # 4-character code
    next_suffix = base36_increment(suffix)
    print(f'{prefix}{next_suffix}')


if __name__ == '__main__':
    main()

