import sys

def next_id(ids_path: str = "ids.txt") -> str:
    with open(ids_path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        return "ORD-0000"

    last = lines[-1]
    prefix, code = last.split("-")

    # increment the base-36 code
    chars = list(code)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if "0" <= c <= "8":
            chars[i] = chr(ord(c) + 1)
            break
        elif c == "9":
            chars[i] = "A"
            break
        elif "A" <= c <= "Y":
            chars[i] = chr(ord(c) + 1)
            break
        elif c == "Z":
            chars[i] = "0"
            # carry to next position
        else:
            # invalid character, default to 0
            chars[i] = "0"
    else:
        # all positions wrapped (ZZZZ -> 0000)
        pass

    return f"{prefix}-{''.join(chars)}"


if __name__ == "__main__":
    print(next_id())

