import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded 4-character base36 string."""
    digits = []
    for _ in range(4):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    n = 0
    for c in s:
        n = n * 36 + BASE36.index(c.upper())
    return n


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if not lines:
        # Start from scratch
        prefix = "ORD-"
        last_suffix = "0000"
    else:
        last_id = lines[-1]
        prefix, last_suffix = last_id[:4], last_id[4:]

    next_num = from_base36(last_suffix) + 1
    next_id = f"{prefix}{to_base36(next_num)}"
    sys.stdout.write(next_id + "\n")


if __name__ == "__main__":
    main()

