"""Print the next order id.

Order ids have the form ORD- followed by a four-character
zero-padded base36 counter.  ids.txt  holds the issued ids, most
recent last; the next id is one more than the last one.
"""

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
WIDTH = 4


def to_base36(value):
    if value == 0:
        return "0"
    chars = []
    while value:
        value, rem = divmod(value, 36)
        chars.append(ALPHABET[rem])
    return "".join(reversed(chars))


def next_suffix(suffix):
    value = 0
    for char in suffix:
        value = value * 36 + ALPHABET.index(char)
    return to_base36(value + 1).rjust(WIDTH, "0")


def main():
    last = None
    with open("ids.txt", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if line:
                last = line
    if last is None:
        print("ORD-" + "0" * WIDTH)
    else:
        suffix = last.split("-", 1)[1]
        print("ORD-" + next_suffix(suffix))


if __name__ == "__main__":
    main()
