#!/usr/bin/env python3
"""Remove duplicate events from events.jsonl based on event_id, preserving first occurrence."""

import json

def main():
    seen = set()
    with open("events.jsonl", "r") as infile, open("deduped.jsonl", "w") as outfile:
        for line in infile:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                outfile.write(line + "\n")

if __name__ == "__main__":
    main()

