#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first occurrence),
and write the remaining events to deduped.jsonl."""

import json

INPUT = "events.jsonl"
OUTPUT = "deduped.jsonl"

def main():
    seen_ids = set()
    with open(INPUT, encoding="utf-8") as inf, open(OUTPUT, "w", encoding="utf-8") as outf:
        for line in inf:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen_ids:
                seen_ids.add(eid)
                outf.write(line + "\n")

if __name__ == "__main__":
    main()

