#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests of all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"

def sha256_digest(filepath):
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

def main():
    manifest = {}
    release_root = os.path.join(os.path.dirname(__file__) or ".", RELEASE_DIR)

    for dirpath, _, filenames in os.walk(release_root):
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(full_path, start=os.path.dirname(release_root))
            manifest[rel_path] = sha256_digest(full_path)

    manifest_path = os.path.join(os.path.dirname(__file__) or ".", MANIFEST_FILE)
    with open(manifest_path, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {len(manifest)} entries to {MANIFEST_FILE}")

if __name__ == "__main__":
    main()

