#!/usr/bin/env python3
import json
import hashlib
from pathlib import Path


RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_hex(filepath: Path) -> str:
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(1 << 20)  # 1 MiB
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if fpath.is_file():
            rel = str(fpath.relative_to(Path.cwd()))
            manifest[rel] = sha256_hex(fpath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)

    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

