#!/usr/bin/env python3
"""Walk release/, compute SHA-256 per file, and write manifest.json."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Return the hex SHA-256 digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for dirpath, _, filenames in os.walk(RELEASE_DIR):
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            # Use forward slashes for cross-platform consistency
            rel_path = os.path.relpath(full_path, start=os.curdir).replace(
                os.sep, "/"
            )
            manifest[rel_path] = sha256_digest(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()

