#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of the file at *filepath*."""
    h = hashlib.sha256()
    with filepath.open("rb") as f:
        while True:
            chunk = f.read(65536)  # 64 KiB
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} does not exist")
        raise SystemExit(1)

    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            relative = path.relative_to(REPO_ROOT).as_posix()
            manifest[relative] = sha256_digest(path)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST_PATH} with {len(manifest)} entries")


if __name__ == "__main__":
    main()

