#!/usr/bin/env python3
"""List report files under reports/ in report order (numeric sort)."""

import os
import re

REPORTS_DIR = "reports"

def report_key(filename: str) -> int:
    """Extract the numeric part of report-<n>.txt for sorting."""
    match = re.search(r'report-(\d+)\.txt$', filename)
    if match:
        return int(match.group(1))
    return -1

def main() -> None:
    if not os.path.isdir(REPORTS_DIR):
        print(f"Error: {REPORTS_DIR}/ not found", file=__import__('sys').stderr)
        return

    files = [f for f in os.listdir(REPORTS_DIR) if re.match(r'report-\d+\.txt$', f)]
    files.sort(key=report_key)

    for f in files:
        print(f)

if __name__ == "__main__":
    main()

