#!/usr/bin/env python3
"""List report files under reports/ in natural numeric order."""

import os
import re

REPORTS_DIR = "reports"


def natural_sort_key(filename: str) -> list:
    """Generate a sort key for natural (human) ordering of numbers in filenames."""
    return [
        int(text) if text.isdigit() else text.lower()
        for text in re.split(r"(\d+)", filename)
    ]


def main() -> None:
    try:
        filenames = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"Error: directory '{REPORTS_DIR}' not found.")
        return

    # Filter to only files (skip subdirectories)
    files = sorted(
        (f for f in filenames if os.path.isfile(os.path.join(REPORTS_DIR, f))),
        key=natural_sort_key,
    )

    for fname in files:
        print(fname)


if __name__ == "__main__":
    main()

