import os
import re
from pathlib import Path

REPORTS_DIR = Path(__file__).resolve().parent / "reports"


def report_sort_key(filename: str) -> int:
    """Extract the numeric part of a report filename for sorting."""
    match = re.search(r"report-(\d+)", filename)
    return int(match.group(1)) if match else 0


def main() -> None:
    if not REPORTS_DIR.is_dir():
        return

    files = [f.name for f in REPORTS_DIR.iterdir() if f.is_file()]
    files.sort(key=report_sort_key)

    for name in files:
        print(name)


if __name__ == "__main__":
    main()

