import os
import re

REPORTS_DIR = "reports"


def numeric_sort_key(filename: str) -> list:
    """Split filename into components for natural (human) sorting.

    e.g. "report-2.txt" → ["report-", 2, ".txt"]
    """
    parts = re.split(r"(\d+)", filename)
    result = []
    for part in parts:
        if part.isdigit():
            result.append(int(part))
        else:
            result.append(part.lower())
    return result


def main() -> None:
    if not os.path.isdir(REPORTS_DIR):
        print(f"error: '{REPORTS_DIR}' directory not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    filenames = sorted(os.listdir(REPORTS_DIR), key=numeric_sort_key)

    for name in filenames:
        print(name)


if __name__ == "__main__":
    main()

