AS_OF is a Unix timestamp in integer seconds. Entries in app.log whose
timestamp is strictly older than 7 days before AS_OF are moved to
archive.log (appended, preserving order). Remaining entries stay in
app.log in their original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str):
    """Return a datetime for the leading 'YYYY-MM-DD HH:MM:SS' or None."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
