"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a leading YYYY-MM-DD HH:MM:SS from line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Invalid timestamp: {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)

    cutoff_epoch = as_of - 7 * 86400  # 7 days in seconds

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{log_path} not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    move: list[str] = []

    for line in lines:
        if not line.strip():
            continue
        ts = parse_timestamp(line)
        if ts is not None and ts.timestamp() < cutoff_epoch:
            move.append(line)
        else:
            keep.append(line)

    # Append moved entries to archive.log (preserving order)
    if move:
        with open(archive_path, "a") as f:
            f.writelines(move)

    # Rewrite app.log with kept entries (preserving order)
    with open(log_path, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

